TXSQ={
'bism':("Bismil-lah","Në emër të Allahut."),
'schahada':("Esh-hedu en la ilahe il-lallahu vahdehu la sherike leh, ve esh-hedu enne Muhammeden abduhu ve resuluh.","Dëshmoj se nuk ka zot tjetër përveç Allahut, Një i Vetëm e pa shok, dhe dëshmoj se Muhammedi është robi dhe i dërguari i Tij."),
'takbir':("Allahu ekber","Allahu është më i Madhi."),
'thana':("Subhaneke Allahumme ve bihamdike, ve tebarekesmuke, ve teala xhedduke, ve la ilahe gajruk.","I lartësuar je Ti, o Allah, dhe falënderimi është për Ty. I bekuar është emri Yt, e lartë është madhëria Jote dhe nuk ka zot tjetër përveç Teje."),
'auudhu':("Eudhu bil-lahi mine-sh-shejtani-r-raxhim. Bismil-lahi-r-rahmani-r-rahim.","Kërkoj mbrojtje te Allahu nga shejtani i mallkuar. Në emër të Allahut, të Gjithëmëshirshmit, Mëshirëplotit."),
'fatiha':("Elhamdu lil-lahi rabbil alemin. Er-rahmani-r-rahim. Maliki jeumid-din. Ijjake na'budu ve ijjake neste'in. Ihdinas-siratal mustekim. Siratal-ledhine en'amte alejhim, gajril magdubi alejhim ve led-dal-lin. Amin.","Falënderimi i takon Allahut, Zotit të botëve, të Gjithëmëshirshmit, Mëshirëplotit, Sunduesit të Ditës së Gjykimit. Vetëm Ty të adhurojmë dhe vetëm prej Teje ndihmë kërkojmë. Udhëzona në rrugën e drejtë, në rrugën e atyre që i ke begatuar, jo të atyre që kanë merituar zemërimin, as të atyre që kanë humbur. Amin."),
'fatiha_b':("Bismil-lahi-r-rahmani-r-rahim. ","Në emër të Allahut, të Gjithëmëshirshmit, Mëshirëplotit. "),
'kauthar':("Inna a'tajnakel keuther. Fesal-li li rabbike venhar. Inne shani'eke huvel ebter.","Ne të kemi dhënë ty bollëkun. Prandaj fal namaz për Zotin tënd dhe ther kurban. Me të vërtetë, urrejtësi yt është ai që është i këputur."),
'ichlas':("Bismil-lahi-r-rahmani-r-rahim. Kul huvallahu ehad. Allahus-samed. Lem jelid ve lem juled. Ve lem jekun lehu kufuven ehad.","Thuaj: Ai është Allahu, Një i Vetëm. Allahu është Ai të cilit të gjithë i drejtohen. As nuk ka lindur kë, as nuk është i lindur. Dhe askush nuk është i barabartë me Të."),
'ruku':("Subhane rabbijel adhim","I lartësuar qoftë Zoti im, i Madhi."),
'qauma':("Semi'allahu limen hamideh. Rabbena lekel hamd.","Allahu e dëgjon atë që e lavdëron. Zoti ynë, Ty të takon lavdërimi."),
'sudschud':("Subhane rabbijel a'la","I lartësuar qoftë Zoti im, Më i Larti."),
'jalsa':("Rabbigfir li","Zoti im, më fal."),
'tahiyyat':("Et-tehijjatu lil-lahi ves-salavatu vet-tajjibat. Es-selamu alejke ejjuhen-nebijju ve rahmetullahi ve berekatuh. Es-selamu alejna ve ala ibadil-lahis-salihin. Esh-hedu en la ilahe il-lallah, ve esh-hedu enne Muhammeden abduhu ve resuluh.","Të gjitha përshëndetjet, lutjet dhe fjalët e mira i takojnë Allahut. Paqja qoftë mbi ty, o Pejgamber, dhe mëshira e Allahut dhe bekimet e Tij. Paqja qoftë mbi ne dhe mbi robërit e mirë të Allahut. Dëshmoj se nuk ka zot tjetër përveç Allahut dhe dëshmoj se Muhammedi është robi dhe i dërguari i Tij."),
'salawat':("Allahumme sal-li ala Muhammedin ve ala ali Muhammed, kema sal-lejte ala Ibrahime ve ala ali Ibrahim, inneke hamidun mexhid. Allahumme barik ala Muhammedin ve ala ali Muhammed, kema barekte ala Ibrahime ve ala ali Ibrahim, inneke hamidun mexhid.","O Allah, lavdëroje Muhammedin dhe familjen e Muhammedit, ashtu siç e lavdërove Ibrahimin dhe familjen e Ibrahimit. Ti je i Lavdishëm, i Madhëruar. O Allah, bekoje Muhammedin dhe familjen e Muhammedit, ashtu siç e bekove Ibrahimin dhe familjen e Ibrahimit. Ti je i Lavdishëm, i Madhëruar."),
'dua':("Rabbena atina fid-dunja haseneten ve fil-ahireti haseneten ve kina adhaben-nar.","Zoti ynë, na jep të mira në këtë botë dhe të mira në botën tjetër, dhe na ruaj nga dënimi i zjarrit."),
'salam':("Es-selamu alejkum ve rahmetullah","Paqja dhe mëshira e Allahut qofshin mbi ju."),
}
